#!/usr/bin/env python3
"""Write a concise, evidence-linked report from measured structured outcomes."""
import argparse,json
from pathlib import Path
def fmt(v,digits=1):return 'Unknown' if v is None else f'{v:,.{digits}f}'
def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();r=a.root
 data=json.loads((r/'report/results.json').read_text());rows=data['rows'];agg=data['aggregate'];complete=sum(x['elapsed_seconds'] is not None for x in rows)
 out=['# Ten-asset Astra / Content Agents pilot','','**No causal workflow advantage is established.** The recorded harness and deployment failures prevent a clean matched comparison.','',f'**Author runs completed: {complete}/20.** Results below include only retained, independently assessed artifacts; pending work is not a pass.','',
 'Both arms used Astra Ultra, the same original source per pair, matched host/GPU placement, shared installed low-level tools, a 40-minute wall-time cap and two declared repairs. The intervention was the public Content Agents workflow. This is a development pilot of the configured runtime. Documented repair dependencies were missing, CPU activity overlapped, and the selected assets are not a random sample. These outcomes do not isolate workflow logic from every deployment effect.','',
 '| Measure | Direct Astra | Astra + Content Agents |','|---|---:|---:|']
 for label,key,kind in [('Independent task passes /10','independently_passing_assets','count'),('Completed author runs','attempted','count'),('Protocol-eligible matched pairs','matched_pair_protocol_eligible','count'),('Passes within protocol-eligible pairs','matched_pair_eligible_accepted','count'),('Runs with observed protocol violations','protocol_invalid_runs','count'),('Concrete rejections','concrete_rejections','count'),('Inconclusive evaluations','inconclusive','count'),('Demonstrated false passes','demonstrated_false_passes','count'),('Authoring time, all attempts (minutes)','total_scored_wall_seconds','minutes'),('Authoring minutes per independent task pass','wall_seconds_per_independently_passing_asset','minutes'),('Allocated GPU hours during authoring','total_allocated_gpu_seconds','hours'),('Observed input tokens, including cached','observed_input_tokens','count'),('Observed cached input tokens','observed_cached_input_tokens','count'),('Observed output tokens','observed_output_tokens','count'),('Runs with complete token accounting','runs_with_complete_token_usage','count'),('Human interventions during authoring','human_interventions','count'),('Human review seconds','human_review_seconds','count'),('Authoring cost per independent task pass (USD)','cost_usd_per_independently_passing_asset','dollars')]:
  vals=[]
  for arm in ('plain_astra','content_agents'):
   v=agg[arm].get(key)
   if kind=='minutes' and v is not None:v/=60
   if kind=='hours' and v is not None:v/=3600
   vals.append('Undefined' if key in ('wall_seconds_per_independently_passing_asset','cost_usd_per_independently_passing_asset') and agg[arm]['independently_passing_assets']==0 else fmt(v,0 if kind=='count' else 2))
  out.append('| '+label+' | '+' | '.join(vals)+' |')
 out+=['','Unknown costs are not zero. Supply nonnegative unit rates with their source and effective date in `protocol/rates.template.json`, then rerun the aggregator. The rate calculation includes every attempt in an arm and uses distinct-session token totals. Shared setup, idle reservation and evaluation costs are separate; allocation time is not GPU-busy time. Unmeasured human review prevents a labor-savings claim.','',
 'Independent physical acceptance and experimental eligibility are separate. A source-code exposure or other protocol violation excludes that pair from the clean comparison even if its saved asset passes physics. Global scheduling compliance and incomplete setup further limit inference; this pilot does not establish a causal workflow advantage.','',
 '| Asset | Direct physical task | Author claim | Direct protocol | Content Agents physical task | Author claim | CA protocol |','|---|---|---|---|---|---|---|']
 for case in sorted({x['case_id'] for x in rows}):
  pair={x['arm']:x for x in rows if x['case_id']==case};b=pair['plain_astra'];c=pair['content_agents']
  def claim(x):return 'Pass' if x['claimed_accepted'] is True else ('Declined' if x['claimed_accepted'] is False else 'None yet')
  def audit(x):return 'Pass' if x['protocol_audit_valid'] is True else ('Invalid' if x['protocol_audit_valid'] is False else 'Unresolved')
  out.append(f"| {case[:2]} {b['asset']} | {b['independent_task_status']} | {claim(b)} | {audit(b)} | {c['independent_task_status']} | {claim(c)} | {audit(c)} |")
 out+=['','A demonstrated false pass requires an explicit pass claim and a concrete independent rejection. Missing deliverables are task rejections; an inadequate evaluator alone is inconclusive. Known numerical evaluator defects must be separately adjudicated and cannot establish false passes. Frozen and corrected measurement records are preserved.','',
 'The direct robot arm exceeded the declared five-degree joint-holding tolerance in all five independent seeds. A separate nominal-controller diagnostic removed stochastic effort terms and still measured a 6.29-degree holding error; [evidence](robot_arm_false_pass_evidence.json). Its source-code exposure is a separate protocol violation. The engine is inconclusive because its remaining rejections concern a contract ambiguity and an evaluator-owned gravity witness defect; raw and corrected records remain available.','', 'The printer evaluator reached its existing 90-minute limit before completing source checks or producing native trials. A [harness-owned closeout](../evaluation_attempts/pilot-v1/09_printer/plain_astra/bounded_closeout_20260922/timeout_assessment.json) records INCONCLUSIVE; no frozen evaluator verdict or false pass is inferred.','', 'The excavator uses explicitly artificial effective rotational inertias, 12 times the source-solid estimates at unchanged mass and center of mass. Any passing articulation result applies to that declared abstraction. The printer uses ideal Cartesian guides and simplified contact geometry; its proposed upward bed stroke does not establish clearance or usable travel in the original hardware. These author disclosures limit what an independent bounded task pass could demonstrate.','',
 'The direct Dextra hand author declined acceptance after two additional effort-factor endpoint probes exceeded the five-degree holding tolerance (5.50 and 5.14 degrees). Passing the five independent seeds establishes that sampled task only; it does not establish robustness over the full effort-variation interval. The author claim remains Declined even if the independent result is PASS.','',
 'Zero false passes must be read with task acceptance: an arm that declines every task has made no positive acceptance claims. It has not demonstrated useful completion merely by avoiding false positives.','', '## Completed physical task: drawer pull','',
 'The direct-Astra drawer passed the unchanged independent source, structure and native-physics checks in all five seeds. The original cabinet and four drawer meshes remain visible. A standalone prismatic joint constrains the upper drawer; applied force opens and closes it while a free 0.5 kg payload remains supported by contact. The minimum opening during the hold was 0.239955 m; the worst closed-hold error was 0.0001859 m. All five trials retained the payload with 2280 contact samples each. Maximum contact penetration was 3.500 mm, below the 5 mm bound.','',
 'At three checked positions, the original visible drawer floor is 4.50 mm above the accepted collision proxy. The frozen payload lower face starts 8.00 mm below that visible floor and 3.50 mm below the proxy; the recorded 5 mm penetration gate measures the proxy. Thus the source checks preserve visual geometry, while physical acceptance applies to the declared collision approximation. [Read-only source/proxy diagnostic](drawer/source_proxy_clearance.json).','',
 '![Five independent measured drawer trajectories](drawer/drawer_validation.png)','',
 'The Content Agents scored drawer stopped at its Geometry handoff and explicitly claimed failure. It did not complete the native workflow chain in the scored trial. Any repaired native-workflow demonstration is a separate unscored follow-up and does not alter these paired outcomes. Mass, inertia, friction and simplified collision shapes are explicit simulation assumptions, not measured furniture properties or real-robot validation.','',
 '## Evidence and reproduction','',
 '- [Method and limitations](METHOD.md).','- [Machine-readable results](results.json) and [CSV](results.csv).','- [Original-source catalog and licensing notes](sources.json); exact byte closures and downloads are in `protocol/`.','- [Geometry failure diagnosis](workflow_geometry_diagnosis.md).','- [Independent method/dependency review](independent_method_review.md).','- [Drawer measured traces and per-seed summaries](drawer/summary.json).','',
 'The public export is an explicit subset of the local retention archive. Credentials, private model reasoning, raw private tool audits and internal service addresses are excluded. Original artifact hashes identify retained evidence. Source-download/rebuild helpers support replay; the included CC0 drawer evidence is the primary self-contained physical example.','']
 (r/'report/RESULTS.md').write_text('\n'.join(out));print(r/'report/RESULTS.md')
if __name__=='__main__':main()
